/**
 * Anzeige der MEZ und der New Yorker-Zeit mit zwei Digitalanzeigen
 * 
 * @author Klaus Dingemann
 * @version 02.01.2017
 */
import sas.*;
import java.awt.Color;
public class Digitaluhr
{
   private View view;
   private Digitalanzeige anzeigeOrtszeit;
   private Digitalanzeige anzeigeNYZeit;
   private Uhrzeit ortszeit;
   private Uhrzeit zeitNY;

    /**
     * Konstruktor für Objekte der Klasse Digitaluhr
     */
   public Digitaluhr()
   {
      view = new View(250, 250, "Digitaluhr");
      ortszeit = new Uhrzeit(0);
      zeitNY = new Uhrzeit(-6);
      anzeigeOrtszeit = new Digitalanzeige(ortszeit, 25, 25, "Münster", Color.RED);
      anzeigeNYZeit = new Digitalanzeige(zeitNY, 25, 125, "New York", Color.BLUE);
   }



   public void fuehreAus() {
      while (!view.keyPressed('q')) {
         anzeigeOrtszeit.setzeZeit(ortszeit);
         anzeigeNYZeit.setzeZeit(zeitNY);
         view.wait(1000);
      }
   }

   public static void main(String[] args) {
      Digitaluhr du = new Digitaluhr();
      du.fuehreAus();
   }
}

/**
 * Objekte dieser KLasse enthalten die aktuelle Uhrzeit
 * 
 * @author Klaus Dingemann
 * @version 30.12.2016
 */

import sas.Tools;
public class Uhrzeit
{
    private int verschiebung;

    public Uhrzeit(int zeitverschiebung)
    {   
       verschiebung = zeitverschiebung;
    }

    public void setzeZeitverschiebung(int zeitverschiebung){
       verschiebung = zeitverschiebung;
    }

    public int gibStunde(){
        return Tools.getHour()+verschiebung;
    }

    public int gibMinute(){
        return Tools.getMinute();
    }

    public int gibSekunde(){
        return Tools.getSecond();
    }

    public String gibZeitString(){
        String zeitstr = "";
        int stunde = gibStunde();
        int minute = gibMinute();
        int sekunde = gibSekunde();
        if (stunde<10) {
            zeitstr = zeitstr + "0" + stunde+":";
        } else {
            zeitstr = zeitstr + stunde + ":";
        }
        if (minute<10) {
            zeitstr = zeitstr + "0" + minute + ":";
        } else {
            zeitstr = zeitstr + minute +":";
        }    
        if (sekunde<10) {
            zeitstr = zeitstr + "0" + sekunde;
        } else {
            zeitstr = zeitstr + sekunde;
        }    
        return zeitstr;
    }

}

/**
 * Erzeugt die Ausgabe einer Digitaluhr
 * 
 * @author Klaus Dingemann
 * @version 01.02.2017
 */
import sas.*;
import java.awt.Color;
public class Digitalanzeige
{
   private Uhrzeit uhrzeit;
   private Text zeitText;

    /**
     * Konstruktor für Objekte der Klasse Digitalanzeige
     */
   public Digitalanzeige(Uhrzeit zeit, double xPos, double yPos, String ort, Color farbe)
   {
      Rectangle gehauese = new Rectangle(xPos, yPos, 200, 80, farbe);
      Rectangle anzeige = new Rectangle(xPos + 6, yPos + 5, 188, 35, Color.WHITE);
      uhrzeit = zeit;
      zeitText = new Text(xPos + 10, yPos + 1, uhrzeit.gibZeitString());
      zeitText. setFontMonospaced(true, 36);
      Text ortText = new Text(xPos + 10, yPos + 40, ort);
      ortText.setFontMonospaced(true, 36);
      ortText.setColor(Color.WHITE);
      double laenge = ortText.getShapeWidth();
      ortText.moveTo(xPos + (200 - laenge) / 2, yPos + 40);
   }

   public void setzeZeit(Uhrzeit zeit) {
      uhrzeit = zeit;
      zeitText.setText(uhrzeit.gibZeitString());
   }


}
